import type { FilterOption } from "@/registry/erbium/lib/filter-rules";

/* Sample tasks for the filter examples. Each example builds its own filters on top of these. */

type Status = "backlog" | "todo" | "in-progress" | "done" | "canceled";

type Priority = "low" | "medium" | "high";

interface Task {
  id: string;
  title: string;
  status: Status;
  priority: Priority;
  labels: string[];
  assignee: string;
  estimate: number;
  due: string;
}

const statusOptions: FilterOption[] = [
  { icon: "circle-fading-plus", label: "Backlog", value: "backlog" },
  { icon: "circle-fading-arrow-up", label: "Todo", value: "todo" },
  { icon: "circle-fading-arrow-up", label: "In progress", value: "in-progress" },
  { icon: "circle-check", label: "Done", value: "done" },
  { icon: "x", label: "Canceled", value: "canceled" },
];

const priorityOptions: FilterOption[] = [
  { label: "Low", value: "low" },
  { label: "Medium", value: "medium" },
  { label: "High", value: "high" },
];

const labelOptions: FilterOption[] = [
  { label: "Bug", value: "bug" },
  { label: "Feature", value: "feature" },
  { label: "Docs", value: "docs" },
  { label: "Design", value: "design" },
];

const titles = [
  "Fix focus ring on menu items",
  "Add RTL support to the date picker",
  "Document the filter bar",
  "Tighten table header spacing",
  "Debounce server-side search",
  "Animate chip removal",
  "Audit color contrast in dark mode",
  "Support multi-select in combobox",
  "Write migration notes for v2",
  "Persist filters in the URL",
  "Reduce bundle size of icons",
  "Add empty state to file tree",
];

const assignees = ["Maya Okafor", "Leo Brandt", "Sana Rahimi", "Aiko Tanaka"];

const statuses: Status[] = ["backlog", "todo", "in-progress", "done", "canceled", "todo"];

const priorities: Priority[] = ["low", "medium", "high", "medium"];

const labelSets = [["bug"], ["feature"], ["docs"], ["design", "feature"], ["bug", "design"], []];

const tasks: Task[] = Array.from({ length: 36 }, (_, index) => ({
  assignee: assignees[index % assignees.length] ?? "Maya Okafor",
  due: new Date(Date.UTC(2026, 10, 1 + ((index * 5) % 40))).toISOString().slice(0, 10),
  estimate: ((index * 7) % 13) + 1,
  id: `TASK-${String(200 + index)}`,
  labels: labelSets[index % labelSets.length] ?? [],
  priority: priorities[index % priorities.length] ?? "low",
  status: statuses[index % statuses.length] ?? "todo",
  title: titles[index % titles.length] ?? "Untitled task",
}));

/** The label of an option value, for cells and list rows. */
const labelOf = (options: FilterOption[], value: string) =>
  options.find((option) => option.value === value)?.label ?? value;

const priorityVariant = { high: "error", low: "secondary", medium: "warning" } as const;

export { labelOf, labelOptions, priorityOptions, priorityVariant, statusOptions, tasks };

export type { Task };

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";
import OverviewExample from "./variants/overview";

import FacetedExample from "./variants/faceted";

import ListExample from "./variants/list";

import RouterExample from "./variants/router";


const meta = {
  parameters: {
    docs: { description: { component: "## Usage

Filters have three layers:

- **Core** (`@/registry/erbium/lib/filter-rules`): field configs, rules, operators and the matcher. A rule is `{ type, operator, values }` and is stored as the value of a TanStack `ColumnFilter`, so `ColumnFiltersState` is the state for tables and lists alike. Rules are plain JSON, so they can go to a server, and `@/registry/erbium/lib/filter-search` writes them to the URL (see [Shareable views](#shareable-views)).
- **Adapters** (`@/registry/erbium/hooks/use-filters`): `useTableFilters(table)` for a TanStack Table v9 table and `useListFilters({ items, fields })` for a plain list. Both return the same `Filters` object.
- **Layouts** (`@/registry/erbium/blocks/filters`): `FilterBar` (chips added from a searchable menu) and `FilterFacets` (one button per field). Both are composed from the same value controls, built on the searchable [Dropdown Menu](/docs/components/dropdown-menu), [Popover](/docs/components/popover), [Number Field](/docs/components/number-field) and [Calendar](/docs/components/calendar).

### Tables

Mark a column filterable with `filterColumn`, which sets both its `filterFn` and its `meta.filter` config. Register the column filtering feature and, for option counts and number ranges, the faceting feature. Control `columnFilters` in the component that calls `useTable`.

```tsx
import { FilterBar } from "@/registry/erbium/blocks/filters";
import { useTableFilters } from "@/registry/erbium/hooks/use-filters";
import { filterColumn } from "@/registry/erbium/lib/filter-rules";
import type { FilterColumnMeta } from "@/registry/erbium/lib/filter-rules";

const features = tableFeatures({
  columnFilteringFeature,
  filteredRowModel: createFilteredRowModel(),
  columnFacetingFeature,
  facetedRowModel: createFacetedRowModel(),
  facetedUniqueValues: createFacetedUniqueValues(),
  facetedMinMaxValues: createFacetedMinMaxValues(),
  columnMeta: {} as FilterColumnMeta,
});

columnHelper.accessor("status", {
  header: "Status",
  ...filterColumn({ type: "option", label: "Status", options: statusOptions }),
});

const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([]);
const table = useTable({
  columns,
  data,
  features,
  state: { columnFilters },
  onColumnFiltersChange: setColumnFilters,
});
const filters = useTableFilters(table);

<FilterBar filters={filters} />;
```

For a server-filtered table, set `manualFiltering: true`, leave out `filteredRowModel`, and send `columnFilters` with the request. The table holds one page, so pass counts from the server with `useTableFilters(table, { counts })` and list `options` in each option field's config.

### Lists

Give `useListFilters` the items and a field config for each filterable field, with a `value` accessor. It returns the `filters` for the layouts and the `items` that pass them.

```tsx
const fields = {
  status: { type: "option", label: "Status", options: statusOptions, value: (task) => task.status },
  due: { type: "date", label: "Due", value: (task) => task.due },
} satisfies Record<string, ListFilterField<Task>>;

const { filters, items } = useListFilters({ items: tasks, fields });
```

Pass `columnFilters` and `onColumnFiltersChange` to keep the rules elsewhere, such as in the URL.

## Shareable views

Keep the rules in the URL and every filtered view becomes a link that can be shared, bookmarked and restored with Back and Forward. `@/registry/erbium/lib/filter-search` maps rules to search params. It does not depend on a router. `useFilterSearch` connects them to a table or list.

Each field with a rule gets one param, named by its id. The value lists the rule's values, separated by commas. When the operator is not the field type's default, the value is prefixed with the operator and a dot:

```text
/tasks?status=todo,in-progress&estimate=between.2,8&title=contains.api&due=onOrAfter.2026-11-01
```

| Param                      | Rule                               |
| -------------------------- | ---------------------------------- |
| `status=todo,in-progress`  | Status is any of Todo, In progress |
| `status=isNoneOf.done`     | Status is not Done                 |
| `estimate=3`               | Estimate is 3                      |
| `estimate=between.2,`      | Estimate is at least 2 (open end)  |
| `title=api`                | Title contains "api"               |
| `due=onOrAfter.2026-11-01` | Due on or after November 1         |
| `title=`                   | A Title filter still being edited  |

The default operators are `contains` for text, `is` for numbers and dates, `isAnyOf` for options and `includesAnyOf` for multi-options. Params come out in the order the filters were added, so a link reopens the chips in that order. Params for other fields are left alone, and a param that does not fit its field (`estimate=abc`) is dropped.

### With TanStack Router

Validate the filter params in the route, then pass the route's search and a navigate call to `useFilterSearch`. The URL is the only copy of the rules; the table reads them from `state` and writes them back through the router.

```tsx
import { createFileRoute } from "@tanstack/react-router";
import { useFilterSearch, useTableFilters } from "@/registry/erbium/hooks/use-filters";
import { getColumnFilterFields, validateFilterSearch } from "@/registry/erbium/lib/filter-search";
import type { FilterSearch } from "@/registry/erbium/lib/filter-search";

// The filterable columns by id and type, read from their `filterColumn(…)` configs.
const filterFields = getColumnFilterFields(columns);

export const Route = createFileRoute("/tasks")({
  validateSearch: (search: FilterSearch & { page?: number }) => ({
    ...validateFilterSearch(search, filterFields),
    page: Math.max(1, Number(search.page ?? 1) || 1),
  }),
  component: TasksPage,
});

function TasksPage() {
  const search = Route.useSearch();
  const navigate = Route.useNavigate();

  const { columnFilters, onColumnFiltersChange } = useFilterSearch({
    fields: filterFields,
    search,
    // Merge into the current search, go back to the first page, and replace the history entry
    // so typing in a text filter does not add a step to Back.
    onSearchChange: (next) => {
      void navigate({ search: (prev) => ({ ...prev, ...next, page: 1 }), replace: true });
    },
  });

  const table = useTable({
    columns,
    data,
    features,
    state: { columnFilters },
    onColumnFiltersChange,
  });
  const filters = useTableFilters(table);

  return <FilterBar filters={filters} />;
}
```

- **Links to a view.** The params are typed through `validateSearch`, so a link to a view is an ordinary `Link`: `<Link to="/tasks" search={{ status: "todo,in-progress", priority: "high" }}>`.
- **Lists.** Pass the list's `fields` (they already carry `type`) and spread the result into `useListFilters`: `useListFilters({ items, fields, ...useFilterSearch({ fields, search, onSearchChange }) })`.
- **Server filtering.** Read the params in `loaderDeps` so each view is its own loader entry and cache key, and send them to the server with `parseFilterSearch(search, filterFields)`. The loader runs again on each change, so debounce text filters before they reach the loader. The URL itself should update on every keystroke.
- **Param names.** Params are named by column id. Rename a column with `id` when its name would clash with another param, such as `page` or `sort`.
- **Other routers.** The codec reads any search object. Use `parseFilterSearch(Object.fromEntries(new URLSearchParams(location.search)), fields)` to read the rules and `toFilterSearch(columnFilters, fields)` to write them, skipping `undefined` values.

## Field types

| Type          | Operators                                                                    | Values                            |
| ------------- | ---------------------------------------------------------------------------- | --------------------------------- |
| `text`        | contains, does not contain, is, is not                                       | One string                        |
| `number`      | is, is not, less than, at most, greater than, at least, between, not between | One number, or a start and an end |
| `date`        | is, is not, before, on or before, after, on or after, between, not between   | `YYYY-MM-DD` keys                 |
| `option`      | is any of, is none of                                                        | Option values                     |
| `multiOption` | includes any of, includes all of, excludes any of, excludes all of           | Option values                     |

Option fields without `options` list the values found in the data. A rule with no values matches everything, so a filter being edited does not hide rows; a text, number or date filter left empty is removed when its editor closes.

## Parts

- `FilterBar`: chip mode. `FilterMenu` adds filters; each active filter is a `FilterChip` with its field, operator menu, value and a remove button.
- `FilterFacets`: faceted mode, one `FilterFacet` per field. Pass `fields` to choose and order them.
- `FilterValueControl`: opens a field's value editor from any trigger. Once a summary only counts the chosen options ("3 selected"), hovering the trigger lists them in a tooltip. Use it to build other layouts.
- `FilterOptionMenu`, `FilterValueEditor`, `FilterOperatorMenu`: the editors the layouts are built from." } },
    layout: "centered",
  },
} satisfies Meta;

export default { ...meta, title: "Blocks/Filters",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj<typeof meta>;

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "Chip mode on a TanStack table. Add a filter from the searchable menu: option fields open a searchable submenu with counts, and text, number and date fields open their editor in a new chip. Change a chip's operator or value in place." },
      source: { code: "import { useState } from "react";
import {
  columnFacetingFeature,
  columnFilteringFeature,
  createColumnHelper,
  createFacetedMinMaxValues,
  createFacetedRowModel,
  createFacetedUniqueValues,
  createFilteredRowModel,
  createPaginatedRowModel,
  metaHelper,
  rowPaginationFeature,
  tableFeatures,
  useTable,
} from "@tanstack/react-table";
import type { ColumnFiltersState, PaginationState } from "@tanstack/react-table";
import { DataTable, DataTableToolbar } from "@/registry/erbium/blocks/data-table";
import { FilterBar } from "@/registry/erbium/blocks/filters";
import { Badge } from "@/registry/erbium/ui/badge";
import { Empty, EmptyDescription, EmptyHeader, EmptyTitle } from "@/registry/erbium/ui/empty";
import { Pagination, PaginationControls } from "@/registry/erbium/ui/pagination";
import { useTableFilters } from "@/registry/erbium/hooks/use-filters";
import { filterColumn } from "@/registry/erbium/lib/filter-rules";
import type { FilterColumnMeta } from "@/registry/erbium/lib/filter-rules";
import {
  labelOf,
  labelOptions,
  priorityOptions,
  priorityVariant,
  statusOptions,
  tasks,
} from "../data";
import type { Task } from "../data";

// Filtering, faceting (option counts and number ranges) and pagination, all on the client.
const features = tableFeatures({
  columnFacetingFeature,
  columnFilteringFeature,
  columnMeta: metaHelper<FilterColumnMeta>(),
  facetedMinMaxValues: createFacetedMinMaxValues(),
  facetedRowModel: createFacetedRowModel(),
  facetedUniqueValues: createFacetedUniqueValues(),
  filteredRowModel: createFilteredRowModel(),
  paginatedRowModel: createPaginatedRowModel(),
  rowPaginationFeature,
});

const columnHelper = createColumnHelper<typeof features, Task>();

// `filterColumn` sets each column's filter function and the config its filter UI reads.
const columns = columnHelper.columns([
  columnHelper.accessor("id", {
    cell: (info) => <span className="font-medium tabular-nums">{info.getValue()}</span>,
    enableColumnFilter: false,
    header: "Task",
  }),
  columnHelper.accessor("title", {
    header: "Title",
    ...filterColumn({ icon: "file-text", label: "Title", type: "text" }),
  }),
  columnHelper.accessor("status", {
    cell: (info) => labelOf(statusOptions, info.getValue()),
    header: "Status",
    ...filterColumn({
      icon: "circle-check",
      label: "Status",
      options: statusOptions,
      type: "option",
    }),
  }),
  columnHelper.accessor("priority", {
    cell: (info) => (
      <Badge variant={priorityVariant[info.getValue()]}>
        {labelOf(priorityOptions, info.getValue())}
      </Badge>
    ),
    header: "Priority",
    ...filterColumn({
      icon: "arrow-up-down",
      label: "Priority",
      options: priorityOptions,
      type: "option",
    }),
  }),
  columnHelper.accessor("labels", {
    cell: (info) =>
      info
        .getValue()
        .map((label) => labelOf(labelOptions, label))
        .join(", "),
    header: "Labels",
    ...filterColumn({
      icon: "tag-01",
      label: "Labels",
      options: labelOptions,
      type: "multiOption",
    }),
  }),
  // No `options`: the choices and their counts come from the rows.
  columnHelper.accessor("assignee", {
    header: "Assignee",
    ...filterColumn({ icon: "user", label: "Assignee", type: "option" }),
  }),
  columnHelper.accessor("estimate", {
    cell: (info) => <div className="text-end tabular-nums">{info.getValue()} h</div>,
    header: () => <div className="text-end">Estimate</div>,
    ...filterColumn({ label: "Estimate", step: 1, type: "number" }),
  }),
  columnHelper.accessor("due", {
    cell: (info) => <span className="tabular-nums">{info.getValue()}</span>,
    header: "Due",
    ...filterColumn({ icon: "calendar-01", label: "Due", type: "date" }),
  }),
]);

// Each rule is a column filter value, so the state is plain `ColumnFiltersState`.
const initialFilters: ColumnFiltersState = [
  { id: "status", value: { operator: "isAnyOf", type: "option", values: ["todo", "in-progress"] } },
];

export default function FiltersOverviewExample() {
  const [columnFilters, setColumnFilters] = useState(initialFilters);
  const [pagination, setPagination] = useState<PaginationState>({ pageIndex: 0, pageSize: 8 });

  const table = useTable({
    columns,
    data: tasks,
    features,
    getRowId: (row) => row.id,
    onColumnFiltersChange: setColumnFilters,
    onPaginationChange: setPagination,
    state: { columnFilters, pagination },
  });

  const filters = useTableFilters(table);

  return (
    <div className="flex w-full min-w-72 max-w-4xl flex-col gap-group p-4">
      <DataTableToolbar>
        <FilterBar filters={filters} />
      </DataTableToolbar>
      <DataTable
        table={table}
        columnWidths={{ estimate: "6.5rem", id: "6.5rem", priority: "6.5rem" }}
        empty={
          <Empty className="border-0">
            <EmptyHeader>
              <EmptyTitle>No tasks match</EmptyTitle>
              <EmptyDescription>Change or clear the filters.</EmptyDescription>
            </EmptyHeader>
          </Empty>
        }
      />
      <div className="flex flex-wrap items-center justify-between gap-related text-caption text-muted-foreground">
        <span aria-live="polite">
          {table.getFilteredRowModel().rows.length} of {tasks.length} tasks
        </span>
        <Pagination className="mx-0 w-auto">
          <PaginationControls
            page={pagination.pageIndex + 1}
            pageCount={Math.max(table.getPageCount(), 1)}
            onPageChange={(target) => {
              setPagination((last) => ({ ...last, pageIndex: target - 1 }));
            }}
          />
        </Pagination>
      </div>
    </div>
  );
}
" },
    },
  },
  render: OverviewExample,
};

export const Faceted: Story = {
  parameters: {
    docs: {
      description: { story: "Faceted mode on the same table: one button per field, showing the chosen values. Option counts follow the other active filters." },
      source: { code: "import { useState } from "react";
import {
  columnFacetingFeature,
  columnFilteringFeature,
  createColumnHelper,
  createFacetedMinMaxValues,
  createFacetedRowModel,
  createFacetedUniqueValues,
  createFilteredRowModel,
  metaHelper,
  tableFeatures,
  useTable,
} from "@tanstack/react-table";
import type { ColumnFiltersState } from "@tanstack/react-table";
import { DataTable, DataTableToolbar } from "@/registry/erbium/blocks/data-table";
import { FilterFacets } from "@/registry/erbium/blocks/filters";
import { Badge } from "@/registry/erbium/ui/badge";
import { Empty, EmptyDescription, EmptyHeader, EmptyTitle } from "@/registry/erbium/ui/empty";
import { useTableFilters } from "@/registry/erbium/hooks/use-filters";
import { filterColumn } from "@/registry/erbium/lib/filter-rules";
import type { FilterColumnMeta } from "@/registry/erbium/lib/filter-rules";
import {
  labelOf,
  labelOptions,
  priorityOptions,
  priorityVariant,
  statusOptions,
  tasks,
} from "../data";
import type { Task } from "../data";

const features = tableFeatures({
  columnFacetingFeature,
  columnFilteringFeature,
  columnMeta: metaHelper<FilterColumnMeta>(),
  facetedMinMaxValues: createFacetedMinMaxValues(),
  facetedRowModel: createFacetedRowModel(),
  facetedUniqueValues: createFacetedUniqueValues(),
  filteredRowModel: createFilteredRowModel(),
});

const columnHelper = createColumnHelper<typeof features, Task>();

const columns = columnHelper.columns([
  columnHelper.accessor("title", { header: "Title" }),
  columnHelper.accessor("status", {
    cell: (info) => labelOf(statusOptions, info.getValue()),
    header: "Status",
    ...filterColumn({
      icon: "circle-check",
      label: "Status",
      options: statusOptions,
      type: "option",
    }),
  }),
  columnHelper.accessor("priority", {
    cell: (info) => (
      <Badge variant={priorityVariant[info.getValue()]}>
        {labelOf(priorityOptions, info.getValue())}
      </Badge>
    ),
    header: "Priority",
    ...filterColumn({
      icon: "arrow-up-down",
      label: "Priority",
      options: priorityOptions,
      type: "option",
    }),
  }),
  columnHelper.accessor("labels", {
    cell: (info) =>
      info
        .getValue()
        .map((label) => labelOf(labelOptions, label))
        .join(", "),
    header: "Labels",
    ...filterColumn({
      icon: "tag-01",
      label: "Labels",
      options: labelOptions,
      type: "multiOption",
    }),
  }),
  columnHelper.accessor("estimate", {
    cell: (info) => <div className="text-end tabular-nums">{info.getValue()} h</div>,
    header: () => <div className="text-end">Estimate</div>,
    ...filterColumn({ label: "Estimate", step: 1, type: "number" }),
  }),
]);

export default function FiltersFacetedExample() {
  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([]);

  const table = useTable({
    columns,
    data: tasks,
    features,
    getRowId: (row) => row.id,
    onColumnFiltersChange: setColumnFilters,
    state: { columnFilters },
  });

  const filters = useTableFilters(table);

  return (
    <div className="flex w-full min-w-72 max-w-4xl flex-col gap-group p-4">
      <DataTableToolbar>
        {/* One button per field; option counts follow the other active filters. */}
        <FilterFacets filters={filters} fields={["status", "priority", "labels", "estimate"]} />
      </DataTableToolbar>
      <div className="max-h-[28rem] overflow-y-auto">
        <DataTable
          table={table}
          columnWidths={{ estimate: "6.5rem", priority: "6.5rem" }}
          empty={
            <Empty className="border-0">
              <EmptyHeader>
                <EmptyTitle>No tasks match</EmptyTitle>
                <EmptyDescription>Change or reset the filters.</EmptyDescription>
              </EmptyHeader>
            </Empty>
          }
        />
      </div>
    </div>
  );
}
" },
    },
  },
  render: FacetedExample,
};

export const List: Story = {
  parameters: {
    docs: {
      description: { story: "Chip mode on a plain list. `useListFilters` keeps the rules, filters the items and counts the options with the same matcher the table uses." },
      source: { code: "import { FilterBar } from "@/registry/erbium/blocks/filters";
import { Badge } from "@/registry/erbium/ui/badge";
import { Empty, EmptyDescription, EmptyHeader, EmptyTitle } from "@/registry/erbium/ui/empty";
import {
  Item,
  ItemContent,
  ItemDescription,
  ItemGroup,
  ItemTitle,
} from "@/registry/erbium/ui/item";
import { useListFilters } from "@/registry/erbium/hooks/use-filters";
import type { ListFilterField } from "@/registry/erbium/hooks/use-filters";
import {
  labelOf,
  labelOptions,
  priorityOptions,
  priorityVariant,
  statusOptions,
  tasks,
} from "../data";
import type { Task } from "../data";

// The same field configs a table column takes, plus a `value` accessor for each field.
const fields = {
  assignee: { icon: "user", label: "Assignee", type: "option", value: (task) => task.assignee },
  due: { icon: "calendar-01", label: "Due", type: "date", value: (task) => task.due },
  labels: {
    icon: "tag-01",
    label: "Labels",
    options: labelOptions,
    type: "multiOption",
    value: (task) => task.labels,
  },
  priority: {
    icon: "arrow-up-down",
    label: "Priority",
    options: priorityOptions,
    type: "option",
    value: (task) => task.priority,
  },
  status: {
    icon: "circle-check",
    label: "Status",
    options: statusOptions,
    type: "option",
    value: (task) => task.status,
  },
  title: { icon: "file-text", label: "Title", type: "text", value: (task) => task.title },
} satisfies Record<string, ListFilterField<Task>>;

export default function FiltersListExample() {
  // `filters` drives the filter UI; `items` are the tasks that pass the active rules.
  const { filters, items } = useListFilters({ fields, items: tasks });

  return (
    <div className="flex w-full min-w-72 max-w-2xl flex-col gap-group p-4">
      <FilterBar filters={filters} />
      <p aria-live="polite" className="text-caption text-muted-foreground">
        {items.length} of {tasks.length} tasks
      </p>
      {items.length === 0 ? (
        <Empty>
          <EmptyHeader>
            <EmptyTitle>No tasks match</EmptyTitle>
            <EmptyDescription>Change or clear the filters.</EmptyDescription>
          </EmptyHeader>
        </Empty>
      ) : (
        <ItemGroup variant="panel" className="max-h-96 overflow-y-auto">
          {items.map((task) => (
            <Item key={task.id} size="sm">
              <ItemContent>
                <ItemTitle>{task.title}</ItemTitle>
